            FROM [dbo].[tblSites]
            WHERE 1=2;
            
        RETURN;
    END

    IF (@sync_batch_size_tblSites IS NULL OR 
        (@sync_batch_size_tblSites IS NOT NULL AND @sync_batch_size_tblSites = 0))
    BEGIN
        SET @sync_batch_size_tblSites = 2147483647;
    END

        SELECT TOP(@sync_batch_size_tblSites) WITH TIES [dbo].[tblSites].[ID],[dbo].[tblSites].[Number],[dbo].[tblSites].[SPLCCode],[dbo].[tblSites].[Address1],[dbo].[tblSites].[Address2],[dbo].[tblSites].[City],[dbo].[tblSites].[State],[dbo].[tblSites].[Zip],[dbo].[tblSites].[Country],[dbo].[tblSites].[Phone],[dbo].[tblSites].[FAX],[dbo].[tblSites].[EmailAddress],[dbo].[tblSites].[EmergencyContact],[dbo].[tblSites].[EmergencyPhone],[dbo].[tblSites].[Enabled],[dbo].[tblSites].[SiteGroupFlag],[dbo].[tblSites].[TimeZone],[dbo].[tblSites].[LevelUnitIndex],[dbo].[tblSites].[TemperatureUnitIndex],[dbo].[tblSites].[DensityUnitIndex],[dbo].[tblSites].[PressureUnitIndex],[dbo].[tblSites].[FlowUnitIndex],[dbo].[tblSites].[VolumeUnitIndex],[dbo].[tblSites].[MassUnitIndex],[dbo].[tblSites].[AdditiveVolumeUnitIndex],[dbo].[tblSites].[AdditiveProfileCycleAmountUnitIndex],[dbo].[tblSites].[AdditiveProfileRateUnitIndex],[dbo].[tblSites].[LevelDecimalPlaces],[dbo].[tblSites].[TemperatureDecimalPlaces],[dbo].[tblSites].[DensityDecimalPlaces],[dbo].[tblSites].[PressureDecimalPlaces],[dbo].[tblSites].[FlowDecimalPlaces],[dbo].[tblSites].[VolumeDecimalPlaces],[dbo].[tblSites].[MassDecimalPlaces],[dbo].[tblSites].[AdditiveVolumeDecimalPlaces],[dbo].[tblSites].[AdditiveProfileCycleAmountDecimalPlaces],[dbo].[tblSites].[AdditiveProfileRateDecimalPlaces],[dbo].[tblSites].[InhibitAccessAfterHours],[dbo].[tblSites].[InhibitMultipleCardIns],[dbo].[tblSites].[AccessCardInRequired],[dbo].[tblSites].[CheckSiteNumber],[dbo].[tblSites].[PromptForCustomerCard],[dbo].[tblSites].[PromptForTractorOrTanker],[dbo].[tblSites].[PromptForFirstTrailer],[dbo].[tblSites].[PromptForSecondTrailer],[dbo].[tblSites].[PromptForCompartment],[dbo].[tblSites].[EnforceDriverEquipmentMatch],[dbo].[tblSites].[EnableAdditiveAccounting],[dbo].[tblSites].[UseCompanyEquipmentIdentifiers],[dbo].[tblSites].[UseLastKnownGoodTankData],[dbo].[tblSites].[MaximumLoadAmount],[dbo].[tblSites].[MaximumLoadTime],[dbo].[tblSites].[Maxi